import type { Content } from './types.ts';

/**
 * Chronicle events from the Yuan to the People's Republic (1279 onwards), in our own words (see docs/data/content.md).
 * Modern history follows the national textbook (统编版) in its positions and terms. The Chinese wording also decides how
 * the app draws an event (jiangshan.ts `kindOf` / `modelOf`), so titles name the act plainly: 攻/破/之战 for battles,
 * 条约 for treaties, 定都/迁都 for capitals. The clause before the first comma is the event's short label.
 */

/** [year, title zh, title en, site zh, site en, lon, lat, map changes?] */
type MRow = [number, string, string, string, string, number, number, boolean?];
/** [n, year, title zh, title en, site zh, site en, lon, lat] */
type LRow = [number, number, string, string, string, string, number, number];

const ms = (dyn: string, rows: MRow[]): Content['milestones'] =>
  rows.map(([year, zh, en, sz, se, lon, lat, map]) => ({
    id: `m-${dyn}-${year}`, dyn, year, title: { zh, en }, site: { zh: sz, en: se }, lon, lat, ...(map ? { map: true } : {}),
  }));
const ls = (dyn: string, rows: LRow[]): Content['landmarks'] =>
  rows.map(([n, year, zh, en, sz, se, lon, lat]) => ({
    id: `l-${dyn}-${n}`, dyn, year, title: { zh, en }, site: { zh: sz, en: se }, lon, lat,
  }));

